declare sid bigint:=coalesce(p_sid,active_subsidiary_id());snap jsonb;
begin
 if app_user_id()is null or not exists(select 1 from user_subsidiaries where user_id=app_user_id()and subsidiary_id=sid)then raise exception 'Sin acceso a la subsidiaria.';end if;
 snap:=statement_snapshot(sid,p_customer,p_cutoff);
 return jsonb_build_object('statement',snap,'history',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'estado',l.estado,'destinatario',l.destinatario,'fecha_corte',l.fecha_corte,'created_at',l.created_at,'enviado_at',l.enviado_at,'ultimo_error',l.ultimo_error)order by l.created_at desc)from comunicaciones_logs l where l.customer_id=p_customer and l.id_subsidiaria=sid and l.tipo_notificacion='ESTADO_CUENTA'),'[]'));
end

declare key uuid;
begin
 perform statement_customer(p_customer,p_cutoff,p_sid);
 if p_request is null then raise exception 'Falta identificador de envío.';end if;
 key:=statement_enqueue(coalesce(p_sid,active_subsidiary_id()),p_customer,p_cutoff,'MANUAL:'||p_request,coalesce(p_note,''),false);
 if key is null then raise exception 'El cliente no tiene saldo pendiente al corte.';end if;
 return(select jsonb_build_object('id',id,'estado',estado)from comunicaciones_logs where id=key);
end

declare sid bigint:=active_subsidiary_id();cfg configuraciones_correos%rowtype;
begin
 if app_user_id()is null or sid is null or not app_is_admin()then raise exception 'Solo un administrador puede configurar las notificaciones.';end if;
 if p_action='save' then
  if length(trim(p_payload->>'subject'))not between 1 and 200 or p_payload->>'subject'~E'[\r\n]' or length(p_payload->>'body')not between 1 and 20000 then raise exception 'Plantilla inválida.';end if;
  insert into configuraciones_correos(id_subsidiaria,tipo_notificacion,asunto_template,cuerpo_template,activo,updated_by_email,envio_dia,envio_hora)
  values(sid,'ESTADO_CUENTA',p_payload->>'subject',p_payload->>'body',coalesce((p_payload->>'active')::boolean,false),'sistema',coalesce((p_payload->>'day')::integer,1),coalesce((p_payload->>'time')::time,'08:00'::time))
  on conflict(id_subsidiaria,tipo_notificacion)do update set asunto_template=excluded.asunto_template,cuerpo_template=excluded.cuerpo_template,activo=excluded.activo,envio_dia=excluded.envio_dia,envio_hora=excluded.envio_hora,updated_at=now();
 elsif p_action<>'get'then raise exception 'Acción inválida.';end if;
 select * into cfg from configuraciones_correos where id_subsidiaria=sid and tipo_notificacion='ESTADO_CUENTA';
 return jsonb_build_object('template',case when cfg.id is null then null else to_jsonb(cfg)||jsonb_build_object('updated_by_email',coalesce(cfg.updated_by_email,to_jsonb(cfg)->>'created_by_email'))end,'subsidiary',(select jsonb_build_object('name',name,'logo',logo_url)from subsidiaries where subsidiary_id=sid));
end

declare report jsonb;rows jsonb:='[]';page integer:=1;balance numeric;result jsonb;
begin
 if p_cutoff is null or p_cutoff>(now()at time zone 'America/Costa_Rica')::date then raise exception 'Fecha de corte inválida.';end if;
 if not exists(select 1 from entity_subsidiaries where subsidiary_id=p_sid and customer_id=p_customer)then raise exception 'El cliente no pertenece a la subsidiaria.';end if;
 loop
  report:=run_aging_report('AR',jsonb_build_object('subsidiaryIds',jsonb_build_array(p_sid),'dateTo',p_cutoff,'agingEntityId',p_customer,'agingCurrencyMode','LOCAL','onlyPending',true,'page',page,'pageSize',250));
  rows:=rows||(report->'rows');exit when page*250>=coalesce((report->>'total')::integer,0);page:=page+1;
 end loop;
 balance:=coalesce((report->'summary'->>'netBalance')::numeric,0);
 select jsonb_build_object('empresa_nombre',s.name,'empresa_logo_url',s.logo_url,'address',s.address,'cliente_nombre',c.company_name,'customerCode',c.customer_number,'email',c.email,'fecha_corte',p_cutoff,'saldo_total',balance,'moneda',m.currency_code,'rows',rows,'summary',report->'summary') into result
 from customers c cross join subsidiaries s join currencies m on m.currency_id=s.currency_id where c.customer_id=p_customer and s.subsidiary_id=p_sid;
 return result;
end

declare report jsonb;rows jsonb:='[]';page int:=1;begin
 if coalesce(auth.role(),'')<>'service_role'and p_sid is distinct from scheduled_report_access()then raise exception 'Sociedad no autorizada.';end if;
 if p_kind not in('AR','AP')or p_kind is null or p_cutoff is null then raise exception 'Reporte o fecha de corte inválidos.';end if;
 loop
 report:=run_aging_report(p_kind,jsonb_build_object('subsidiaryIds',jsonb_build_array(p_sid),'dateTo',p_cutoff,'agingCurrencyMode','LOCAL','onlyPending',true,'page',page,'pageSize',250));
 if coalesce((report->>'total')::int,0)>20000 then raise exception 'El reporte supera 20.000 documentos. No se enviará un archivo incompleto.';end if;
 rows:=rows||coalesce(report->'rows','[]');exit when page*250>=coalesce((report->>'total')::int,0);page:=page+1;
 end loop;
 return jsonb_build_object('kind',p_kind,'cutoff',p_cutoff,'company',(select name from subsidiaries where subsidiary_id=p_sid),'currency',(select c.currency_code from subsidiaries s join currencies c using(currency_id)where s.subsidiary_id=p_sid),'rows',rows,'summary',report->'summary');
end

declare old_claims text:=current_setting('request.jwt.claims',true);owner_email text;filters jsonb;report jsonb;rows jsonb:='[]';result jsonb;page int:=1;count_rows int;date_from date;period_key bigint;mode text:=coalesce(p_options->>'periodMode','YEAR_TO_DATE');book_key bigint;
begin
 if coalesce(auth.role(),'')='service_role'then
 if p_owner is null or not scheduled_report_owner_allowed(p_owner,p_sid)then raise exception 'El propietario no tiene acceso a reportes de esta sociedad.';end if;
 select email into owner_email from users where user_id=p_owner;
 perform set_config('request.jwt.claims',(coalesce(nullif(old_claims,'')::jsonb,'{}')||jsonb_build_object('email',owner_email,'scheduled_report_sid',p_sid))::text,true);
 elsif p_sid is distinct from scheduled_report_access()then raise exception 'Sociedad no autorizada.';end if;
 perform scheduled_report_validate_options(p_sid,p_kind,p_options);
 if p_cutoff is null then raise exception 'Seleccione la fecha de corte.';end if;
 if p_kind in('AR','AP')then result:=scheduled_report_snapshot(p_sid,p_kind,p_cutoff);
 else
 date_from:=case mode when 'YEAR_TO_DATE'then date_trunc('year',p_cutoff)::date when 'MONTH_TO_DATE'then date_trunc('month',p_cutoff)::date when 'LAST_7_DAYS'then p_cutoff-6 when 'LAST_30_DAYS'then p_cutoff-29 end;
 if date_from is null then raise exception 'Período relativo inválido.';end if;
 book_key:=nullif(p_options->>'bookId','')::bigint;
 if book_key is null then select accounting_book_id into book_key from accounting_books where subsidiary_id=p_sid and is_active and is_primary order by accounting_book_id limit 1;end if;
 filters:=jsonb_build_object('subsidiaryIds',jsonb_build_array(p_sid),'dateFrom',date_from,'dateTo',p_cutoff,'from',date_from,'to',p_cutoff,'bookId',book_key,'bankAccountId',nullif(p_options->>'bankAccountId','')::bigint,'bankView','AUXILIARY','hierarchy',4,'excludeZero',true,'pageSize',250);
 if p_kind='bank-balances'then
 select fiscal_period_id into period_key from fiscal_periods where subsidiary_id=p_sid and start_date<=p_cutoff and end_date>=p_cutoff order by end_date-start_date,fiscal_period_id limit 1;
 if period_key is null then raise exception 'No existe período contable para la fecha de corte.';end if;
 select start_date,end_date into date_from,p_cutoff from fiscal_periods where fiscal_period_id=period_key;
 filters:=filters||jsonb_build_object('periodId',period_key);
 end if;
 loop
 filters:=filters||jsonb_build_object('page',page);
 case p_kind
 when 'pending-invoice-control'then report:=run_pending_invoice_control_report(filters);
 when 'journal'then report:=run_general_journal_report(filters);
 when 'sales-transactions'then report:=run_sales_transaction_report(filters);
 when 'purchase-transactions'then report:=run_purchase_transaction_report(filters);
 when 'bank-reconciliation'then report:=run_bank_reconciliation_report(filters);
 when 'bank-balances'then report:=run_bank_balance_period_report(filters);
 when 'fx-revaluation'then report:=fx_report(filters);
 when 'asset-reconciliation','asset-projection','asset-impairment'then
 report:=fixed_asset_analytics(filters);
 report:=case p_kind when 'asset-reconciliation'then jsonb_build_object('rows',report->'reconciliation')when 'asset-projection'then jsonb_build_object('rows',report->'projection')else jsonb_build_object('impairments',report->'impairments','disposals',report->'disposals')end;
 else report:=run_accounting_report(p_kind,filters);
 end case;
 count_rows:=jsonb_array_length(coalesce(report->'rows','[]'));
 rows:=rows||coalesce(report->'rows','[]');
 if jsonb_array_length(rows)>20000 or coalesce((report->>'total')::int,0)>20000 then raise exception 'El reporte supera 20.000 filas. No se enviará un archivo incompleto.';end if;
 exit when not(report ? 'rows') or jsonb_array_length(rows)>=coalesce((report->>'total')::int,count_rows);
 if count_rows=0 or page>=2000 then raise exception 'No fue posible recuperar todas las páginas del reporte.';end if;
 page:=page+1;
 end loop;
 if report ? 'rows'then report:=report||jsonb_build_object('rows',rows);end if;
 if p_kind='bank-reconciliation'then
 report:=jsonb_build_object('rows',rows,'summary',report->'summary','bankAccount',(select jsonb_build_object('account',b.account_number,'bank',bk.bank_name,'currency',c.currency_code)from bank_account b join banks bk using(bank_id)join currencies c using(currency_id)where b.bank_account_id=(p_options->>'bankAccountId')::bigint));
 end if;
 if p_kind in('asset-reconciliation','asset-projection')then report:=report||jsonb_build_object('scopeNote','El auxiliar utiliza las fichas actuales de activos. La proyección incluye las depreciaciones registradas a la fecha de generación.');end if;
 result:=jsonb_build_object('kind',p_kind,'cutoff',p_cutoff,'dateFrom',date_from,'company',(select name from subsidiaries where subsidiary_id=p_sid),'currency',(select c.currency_code from subsidiaries s join currencies c using(currency_id)where s.subsidiary_id=p_sid),'rows','[]'::jsonb,'summary','{}'::jsonb,'data',report);
 end if;
 result:=result||jsonb_build_object('title',(select name from scheduled_report_catalog where code=p_kind));
 perform set_config('request.jwt.claims',coalesce(old_claims,''),true);return result;
exception when others then perform set_config('request.jwt.claims',coalesce(old_claims,''),true);raise;
end

declare sid bigint:=active_subsidiary_id();begin
 if app_user_id()is null or not exists(select 1 from user_subsidiaries where user_id=app_user_id()and subsidiary_id=sid)
 or not(app_is_admin()or exists(select 1 from role_permissions rp join permissions p using(permission_id)where rp.role_id=app_active_role_id()and p.code='REPORT_SCHEDULE_MANAGE'))then raise exception using errcode='42501',message='No tiene permiso para administrar envíos programados en esta sociedad.';end if;
 return sid;
end
